import { BRAND_IMAGES } from '../../constants/legal';
import type { SeedCourseDef, SeedStudyNoteDef } from './departments';

export function makeBusinessNote(cfg: {
  id: string;
  moduleId: string;
  lessonId: string;
  title: string;
  intro: string;
  simple: string;
  detailed: string;
  concepts: string;
  steps: string;
  practicalExamples: string;
  realWorld: string;
  important: string;
  mistakes: string;
  summary: string;
  shortQ: string;
  longQ: string;
  mcq: string;
  campaignExample: string;
  toolsStrategies: string;
  planningExercise: string;
}): SeedStudyNoteDef {
  return {
    id: cfg.id,
    moduleId: cfg.moduleId,
    lessonId: cfg.lessonId,
    title: cfg.title,
    topicIntroduction: cfg.intro,
    simpleExplanation: cfg.simple,
    detailedExplanation: cfg.detailed,
    keyConcepts: cfg.concepts,
    stepByStepExplanation: cfg.steps,
    practicalExamples: cfg.practicalExamples,
    realWorldApplications: cfg.realWorld,
    importantPoints: cfg.important,
    commonMistakes: cfg.mistakes,
    summary: cfg.summary,
    practiceQuestions: [
      '### Short-Answer Questions',
      cfg.shortQ,
      '',
      '### Long-Answer Questions',
      cfg.longQ,
      '',
      '### Multiple-Choice Questions (With Answers & Explanations)',
      cfg.mcq,
    ].join('\n'),
    domainSupplement: [
      '### Real Campaign & Business Scenario',
      cfg.campaignExample,
      '',
      '### Industry Tools & Execution Strategy',
      cfg.toolsStrategies,
      '',
      '**Campaign Planning Exercise:**',
      cfg.planningExercise,
    ].join('\n'),
  };
}

